CREATE POLICY financeiro_comprovantes_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='financeiro-comprovantes' AND private.financeiro_autorizado());
CREATE POLICY financeiro_comprovantes_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='financeiro-comprovantes' AND private.financeiro_autorizado());
CREATE POLICY financeiro_comprovantes_update ON storage.objects FOR UPDATE TO authenticated USING(bucket_id='financeiro-comprovantes' AND private.financeiro_autorizado()) WITH CHECK(bucket_id='financeiro-comprovantes' AND private.financeiro_autorizado());
DO $do$ DECLARE f text; BEGIN SELECT pg_get_functiondef('public.financeiro_operar(text,jsonb,uuid)'::regprocedure) INTO f;
f=replace(f,' id uuid;',' v_id uuid;');f=replace(f,'WHERE id;','WHERE id=true;');f=replace(f,' THEN id=',' THEN v_id=');f=replace(f,';id=',';v_id=');f=replace(f,' id=c.id;',' v_id=c.id;');f=replace(f,' INTO id;',' INTO v_id;');f=replace(f,'VALUES(id,','VALUES(v_id,');f=replace(f,'WHERE cobranca_id=id','WHERE cobranca_id=v_id');f=replace(f,'WHERE a.cobranca_id=id','WHERE a.cobranca_id=v_id');f=replace(f,'WHERE financeiro_cobrancas.id=id','WHERE financeiro_cobrancas.id=v_id');f=replace(f,'WHERE financeiro_pagamentos.id=id','WHERE financeiro_pagamentos.id=v_id');f=replace(f,'WHERE fonte_credito=id','WHERE fonte_credito=v_id');f=replace(f,'private.financeiro_saldo(id,','private.financeiro_saldo(v_id,');f=replace(f,$s$jsonb_build_object('id',id)$s$,$s$jsonb_build_object('id',v_id)$s$);f=replace(f,'residente_id=rid AND NOT cancelada ORDER BY','residente_id=rid AND emissao<=d AND NOT cancelada ORDER BY');
f=replace(f,$s$ELSIF _acao='pagamento' THEN$s$,$s$ELSIF _acao='pagamento' OR _acao='credito' THEN$s$);
f=replace(f,'pid=gen_random_uuid();INSERT',$s$IF _acao='credito' THEN SELECT p.id,p.valor_centavos-coalesce((SELECT sum(a.principal_centavos+a.multa_centavos+a.juros_centavos+a.correcao_centavos) FROM public.financeiro_alocacoes a WHERE a.pagamento_id=p.id),0)-coalesce((SELECT sum(u.valor_centavos) FROM public.financeiro_pagamentos u WHERE u.fonte_credito=p.id AND NOT u.estornado),0) livre INTO r FROM public.financeiro_pagamentos p WHERE p.id=(_dados->>'fonte_credito')::uuid AND p.residente_id=rid AND NOT p.estornado AND p.forma<>'credito' FOR UPDATE; IF NOT FOUND OR r.livre<v THEN RAISE EXCEPTION 'Crédito insuficiente'; END IF; END IF; pid=gen_random_uuid();INSERT$s$);
f=replace(f,$s$VALUES(pid,rid,d,v,_dados->>'forma'$s$,$s$VALUES(pid,rid,d,v,CASE WHEN _acao='credito' THEN 'credito' ELSE _dados->>'forma' END$s$);
f=replace(f,'restante=v; FOR c IN',$s$IF _acao='credito' THEN UPDATE public.financeiro_pagamentos SET fonte_credito=r.id WHERE financeiro_pagamentos.id=pid; END IF; restante=v; FOR c IN$s$);
f=replace(f,$s$res=jsonb_build_object('id',pid,'credito',restante);$s$,$s$IF _acao='credito' AND restante>0 THEN RAISE EXCEPTION 'O crédito aplicado excede as dívidas selecionadas'; END IF; res=jsonb_build_object('id',pid,'credito',restante);$s$);
f=replace(f,'IF selecionadas IS NOT NULL AND jsonb_array_length(selecionadas)>0 THEN FOR x',$s$IF _dados ? 'alocacoes' AND jsonb_array_length(selecionadas)=0 THEN RAISE EXCEPTION 'Escolha pelo menos uma cobrança'; END IF; IF selecionadas IS NOT NULL AND jsonb_array_length(selecionadas)>0 THEN FOR x$s$);
EXECUTE f; END $do$;
CREATE FUNCTION public.financeiro_previa(_residente uuid,_data date) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF NOT private.financeiro_autorizado() THEN RAISE EXCEPTION 'Acesso financeiro não autorizado'; END IF; RETURN (SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'calculo',private.financeiro_saldo(c.id,_data)) ORDER BY c.vencimento),'[]') FROM public.financeiro_cobrancas c WHERE c.residente_id=_residente AND c.emissao<=_data AND NOT c.cancelada);END; $$;
REVOKE ALL ON FUNCTION public.financeiro_previa(uuid,date) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.financeiro_previa(uuid,date) TO authenticated;
CREATE FUNCTION private.financeiro_auditoria_imutavel() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'A auditoria financeira não pode ser alterada ou excluída'; END; $$;
REVOKE ALL ON FUNCTION private.financeiro_auditoria_imutavel() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER financeiro_auditoria_imutavel BEFORE UPDATE OR DELETE ON public.financeiro_auditoria FOR EACH ROW EXECUTE FUNCTION private.financeiro_auditoria_imutavel();